add_filter( 'woocommerce_my_account_my_orders_actions', 'perfectpixel_order_again_action', 50, 2 );

function perfectpixel_order_again_action( $actions, $order ) {
	$statuses = apply_filters( 'woocommerce_valid_order_statuses_for_order_again', array( 'completed' ) );
	if ( $order && $order->has_status( $statuses ) && $order->get_item_count() > 0 ) {
		$actions['order-again'] = array(
			// Same URL as the core "Order again" button, so WooCommerce's own handler fills the cart.
			'url'  => wp_nonce_url( add_query_arg( 'order_again', $order->get_id(), wc_get_cart_url() ), 'woocommerce-order_again' ),
			'name' => '{{order_again_label}}',
		);
	}
	return $actions;
}
